import { Alert, Box, HStack } from "@chakra-ui/react";
import { useCallback, useMemo, useState } from "react";
import {
  type Conversation,
  type ConversationEventAction,
  type UnionEventType,
  UtteranceType,
} from "../types";
import { formatDateTime, isBotUtteranceEmpty, isConversationEvent, isUtterance } from "../utils";
import { useInspectorStore } from "../store";
import { selectIsMantleEngine } from "../store/selectors";
import { ConversationLoadingSpinner } from "./ConversationLoadingSpinner";
import { Event as ConversationEventComponent } from "./ConversationLog/Event";
import {
  groupEventsByToolCall,
  type ConversationLogItem,
} from "./ConversationLog/groupEventsByToolCall";
import { Message } from "./ConversationLog/Message/Message";

interface ConversationSessionProps {
  interactive?: boolean;
  conversation: Conversation;
  assistantVersion?: string;
  onQuickReply?: (payload: string, title: string) => void;
  selectable?: boolean;
  onSelect?: (selection: UnionEventType) => void;
  selectedElementId?: string;
  inspectorMode: boolean;
  replayConversation?: (eventId: string) => void;
  waitingForResponse?: boolean;
  replayingConversation?: boolean;
  conversationEventActions?: ConversationEventAction[];
}

export const ConversationSession = ({
  conversation,
  onQuickReply,
  selectable = false,
  onSelect,
  selectedElementId,
  inspectorMode,
  replayConversation,
  interactive = false,
  waitingForResponse = false,
  replayingConversation = false,
  assistantVersion,
  conversationEventActions,
}: ConversationSessionProps) => {
  const { events = [] } = conversation;

  const formattedStartDate = formatDateTime(new Date(conversation.startDate));
  const formattedEndDate = conversation.endDate
    ? formatDateTime(new Date(conversation.endDate))
    : undefined;

  const isMantleEngine = useInspectorStore(selectIsMantleEngine);

  const shownEvents = useMemo(
    () =>
      events.filter(
        (event) =>
          (isUtterance(event) && !isBotUtteranceEmpty(event)) || isConversationEvent(event),
      ),
    [events],
  );

  // Skill engine: memory writes collapse under the tool call that produced
  // them (matched via the mantle_write_provenance stamp).
  const logItems: ConversationLogItem[] = useMemo(
    () =>
      isMantleEngine
        ? groupEventsByToolCall(shownEvents)
        : shownEvents.map((event) => ({ kind: "event", event })),
    [isMantleEngine, shownEvents],
  );
  const [expandedCalls, setExpandedCalls] = useState<Record<string, boolean>>({});
  const toggleCall = useCallback((callId: string) => {
    setExpandedCalls((previous) => ({ ...previous, [callId]: !previous[callId] }));
  }, []);

  const lastUtterance = shownEvents.findLast((event) => isUtterance(event));
  const lastEventId = shownEvents[shownEvents.length - 1]?.id;

  // only the last bot utterance can be interactive - and only if it is really
  // the last utterance and there is no user utterance after it
  const interactiveBotUtteranceId =
    lastUtterance?.type === UtteranceType.Bot ? lastUtterance.id : undefined;

  const handleSelect = useCallback(
    (selection: UnionEventType) => {
      if (inspectorMode) {
        onSelect?.(selection);
      }
    },
    [onSelect, inspectorMode],
  );

  return (
    <Box mt="4" mb="4">
      <HStack px="6" py="2" width="100%" justifyContent="center">
        <Alert.Root size="sm" justifyContent="center">
          <Alert.Title>
            Session started on {formattedStartDate} {assistantVersion || ""}
          </Alert.Title>
        </Alert.Root>
      </HStack>

      {logItems.map((item) => {
        if (item.kind === "tool-group" || item.kind === "llm-group") {
          if (!inspectorMode) return null;
          const callKey = item.call.id;
          const expanded = expandedCalls[callKey] ?? false;
          const toggleProps =
            item.kind === "tool-group"
              ? {
                  toolCallExpanded: expanded,
                  onToolCallToggle:
                    item.children.length > 0 ? () => toggleCall(callKey) : undefined,
                }
              : {
                  llmCallExpanded: expanded,
                  onLlmCallToggle: item.children.length > 0 ? () => toggleCall(callKey) : undefined,
                };
          return (
            <Box key={item.call.id}>
              <ConversationEventComponent
                event={item.call}
                selectable={selectable}
                onEventSelect={handleSelect}
                isSelected={item.call.id === selectedElementId}
                replayConversation={replayConversation}
                isLastActiveEvent={item.call.id === lastEventId && interactive}
                conversationEventActions={conversationEventActions}
                {...toggleProps}
              />
              {expanded && item.children.length > 0 ? (
                <Box
                  ml="7"
                  borderLeftWidth="1px"
                  borderColor="border"
                  data-testid="tool-call-group"
                >
                  {item.children.map((child) => (
                    <ConversationEventComponent
                      key={child.id}
                      event={child}
                      selectable={selectable}
                      onEventSelect={handleSelect}
                      isSelected={child.id === selectedElementId}
                      replayConversation={replayConversation}
                      isLastActiveEvent={child.id === lastEventId && interactive}
                      conversationEventActions={conversationEventActions}
                    />
                  ))}
                </Box>
              ) : null}
            </Box>
          );
        }

        const event = item.event;
        const isSelected = event.id === selectedElementId;
        if (isUtterance(event)) {
          return (
            <Message
              key={event.id}
              utterance={event}
              isInteractive={interactive && event.id === interactiveBotUtteranceId}
              onQuickReply={onQuickReply}
              onMessageSelect={handleSelect}
              isSelected={isSelected}
              selectable={selectable}
              inspectorMode={inspectorMode}
              conversationEventActions={conversationEventActions}
            />
          );
        } else if (isConversationEvent(event)) {
          return inspectorMode ? (
            <ConversationEventComponent
              key={event.id}
              event={event}
              selectable={selectable}
              onEventSelect={handleSelect}
              isSelected={isSelected}
              replayConversation={replayConversation}
              isLastActiveEvent={event.id === lastEventId && interactive}
              conversationEventActions={conversationEventActions}
            />
          ) : null;
        }
      })}
      {waitingForResponse || replayingConversation ? <ConversationLoadingSpinner /> : null}

      {formattedEndDate && (
        <HStack px="6" py="2" width="100%" justifyContent="center">
          <Alert.Root size="sm" justifyContent="center">
            <Alert.Title>Session ended on {formattedEndDate}</Alert.Title>
          </Alert.Root>
        </HStack>
      )}
    </Box>
  );
};
